/**
 * Session-render screenshot harness. Renders the REAL product components (via
 * their original import paths) over invented fixtures, so the same page
 * screenshots identically before and after the session-core / session-ui
 * extraction. Layout uses inline styles only: this directory is deliberately
 * outside Tailwind's `content` globs, so a purged product class shows up as a
 * pixel diff instead of being silently re-generated by the harness.
 *
 *   ?fixture=pi|claude|antigravity|commandcode|strips  [&theme=dark]
 */
import React from 'react';
import ReactDOM from 'react-dom/client';
import '../src/index.css';
import { VirtualizedMessageList } from '../src/components/Chat/VirtualizedMessageList';
import { GoalPanel } from '../src/components/Chat/GoalPanel';
import { ChildrenStrip } from '../src/components/Chat/ChildrenStrip';
import { WatchStrip } from '../src/components/Chat/WatchStrip';
import { useSessionStore } from '../src/store/sessionStore';
import { useBackgroundChildrenStore } from '../src/store/backgroundChildrenStore';
import { useWatchSurfacingStore } from '../src/store/watchSurfacingStore';
import { useGoalStore } from '../src/store/goalStore';
import type { LiveMessage } from '../src/hooks/useSessionStream';
import pi from '../../fixtures/session-render/__golden__/pi.messages.json';
import claude from '../../fixtures/session-render/__golden__/claude.messages.json';
import antigravity from '../../fixtures/session-render/__golden__/antigravity.messages.json';
import commandcode from '../../fixtures/session-render/__golden__/commandcode.messages.json';

const params = new URLSearchParams(window.location.search);
const fixture = params.get('fixture') ?? 'pi';
if (params.get('theme') === 'dark') document.documentElement.classList.add('dark');

const SESSION_ID = `fixture-${fixture}-session`;
const SDK: Record<string, string> = { pi: 'pi', claude: 'claude', antigravity: 'antigravity', commandcode: 'commandcode', strips: 'pi' };

/** A Pi subagent result carrying the server-computed summary (rich card). */
const subagentMessage: LiveMessage = {
  id: 'pi-t7',
  role: 'tool',
  content: [{ type: 'text', text: 'The demo widget is only used by the sample page.' }],
  timestamp: 1_700_000_000_000,
  isComplete: true,
  toolCall: { id: 'pi-t7', name: 'subagent', args: { agent: 'scout', task: 'Find usages of the demo widget' } },
  toolResult: {
    output: 'The demo widget is only used by the sample page.',
    isError: false,
    summary: {
      mode: 'single',
      kind: 'subagent',
      agents: [{
        agent: 'scout', model: 'example-provider/example-model', task: 'Find usages of the demo widget',
        turns: 3, toolCalls: 2, toolBreakdown: [{ name: 'grep', count: 1 }, { name: 'read', count: 1 }],
        inputTokens: 21_000, outputTokens: 900,
      }],
      totals: { agentCount: 1, toolCalls: 2, turns: 3, inputTokens: 21_000, outputTokens: 900 },
    },
  },
};

const transcripts: Record<string, LiveMessage[]> = {
  pi: [...(pi.live as LiveMessage[]), subagentMessage],
  claude: claude.live as LiveMessage[],
  antigravity: antigravity.live as LiveMessage[],
  commandcode: commandcode.live as LiveMessage[],
};

useSessionStore.setState({
  currentSessionId: SESSION_ID,
  currentSessionSdkType: SDK[fixture] as never,
  isStreaming: false,
  historyReplayActive: {},
});

function Strips(): JSX.Element {
  return (
    <div style={{ maxWidth: 896, margin: '0 auto', padding: 16 }}>
      <GoalPanel sessionId={SESSION_ID} sdkType="pi" isStreaming={false} statusText={undefined} onControl={() => {}} />
      <ChildrenStrip sessionId={SESSION_ID} />
      <WatchStrip sessionId={SESSION_ID} />
    </div>
  );
}

if (fixture === 'strips') {
  useGoalStore.getState().applyWidget(SESSION_ID, [
    '🎯 Goal Status',
    'Status: ▶ Running',
    'Objective: Create three sample files',
    'Started: 11/14/2023, 10:00:00 PM',
    'Agent runs: 1',
    'Max runs: 4',
    'Token spend: 12,000 / 5,000,000 billed input tokens',
    'Verification command: test -f a.txt',
    'Verification status: failed',
    '',
    'Plan:',
    '  ✓ Inspect workspace',
    '  ☐ Write the files',
  ]);
  useBackgroundChildrenStore.getState().applyChildren(SESSION_ID, [
    { id: 'bg_1', kind: 'background_subagent', status: 'running', label: 'sample-researcher', model: 'example-provider/example-model' },
    { id: 'c-2', kind: 'internal_api_child', status: 'running', label: 'pi child c-2', runtime: 'pi', model: 'example/fast' },
  ]);
  useWatchSurfacingStore.getState().upsert(SESSION_ID, {
    watchId: 'watch-c-2', targetSessionId: 'c-2', status: 'active', label: 'sample-watch',
    conditions: [{ type: 'event_type', description: 'event agent_end' }],
  });
}

function App(): JSX.Element {
  if (fixture === 'strips') return <Strips />;
  return (
    <div data-testid="harness-transcript" style={{ height: 1700, display: 'flex', flexDirection: 'column' }}>
      <VirtualizedMessageList messages={transcripts[fixture] ?? []} isStreaming={false} sessionId={SESSION_ID} hasSession />
    </div>
  );
}

ReactDOM.createRoot(document.getElementById('root') as HTMLElement).render(<App />);
